using System.Linq;
using UnityEngine;
namespace BWVR {
// Extends the existing leisure controller, not a second locomotion owner.
public sealed partial class VillagerExploration {
 CreatureConstructionLearning construction;ConstructionSite structure;Vector3 structureGoal;bool entered;
 public bool ShowingBuildingNeed=>Current==Phase.ShowNeed;
 public void ConfigureConstruction(CreatureConstructionLearning learning){construction=learning;}
 bool CanStartStructure=>!routine.Worshipping&&!routine.BuildingCathedral&&GetComponentInParent<QuestSlice>()?.GetComponentInChildren<VillageFamilies>()?.Owns(GetComponent<VillagerRoutine>())!=true&&GetComponent<VillagerResourceGathering>()?.Active!=true&&!Active&&!actor.held&&!social.Active&&!(GetComponent<VillagerBlockPlay>()?.Active??false);
 bool ChooseStructure(){if(construction==null)return false;if(ChooseShelter())return true;foreach(var site in construction.sites.Where(s=>!s.IsBridge&&s.RecipeComplete).OrderBy(s=>(s.transform.position-transform.position).sqrMagnitude)){bool unseen=(social.Memory.usedForms&(1<<(int)site.Recipe))==0;if((unseen||(site.Recipe==BuildRecipe.Bench&&social.Memory.restNeed>.65f))&&TryStructure(site))return true;}if(social.Memory.restNeed>.65f&&construction.GetComponent<CreatureHybrid>().State.time>=social.Memory.nextBuildingRequest)foreach(var site in construction.sites.Where(s=>!s.IsBridge&&(s.Snapped==0||(s.Recipe==BuildRecipe.Bench&&!s.RecipeComplete))).OrderBy(s=>(s.transform.position-transform.position).sqrMagnitude))if(TryBuildingNeed(site))return true;return false;}
 public bool TryStructure(ConstructionSite site){if(!CanStartStructure||site==null||site.IsBridge||!site.RecipeComplete||(site.Visitor!=null||site.Repairer!=null))return false;if(!world.Reachable(transform.position,site.World(new Vector3(0,0,-4)),nav.profile))return false;structure=site;site.Visitor=this;routine.ResetTask();nav.ResetRoute();clock=elapsed=0;entered=false;structureGoal=site.World(new Vector3(0,0,-4));Current=Phase.ApproachStructure;motion?.LookAt(site.transform);return true;}
 public bool TryBuildingNeed(ConstructionSite site){if(!CanStartStructure||construction==null||site==null||site.IsBridge||(site.Snapped!=0&&site.Recipe!=BuildRecipe.Bench)||(site.Requester!=null||site.Repairer!=null)||social.Memory.restNeed<=.65f)return false;if(!world.Reachable(transform.position,site.World(new Vector3(0,0,-11)),nav.profile))return false;structure=site;site.Requester=this;routine.ResetTask();nav.ResetRoute();clock=elapsed=0;Current=Phase.NeedApproach;return true;}
 bool TickStructure(float dt){clock+=dt;elapsed+=dt;if(structure==null||elapsed>180){ResetTask();return false;}if(shelterVisit)return TickShelter(dt);var site=structure;var god=construction.GetComponent<CreatureHybrid>();
  if(Current==Phase.NeedApproach){if(site.Snapped>0&&site.Recipe!=BuildRecipe.Bench){ResetTask();return false;}if(nav.MoveTo(site.World(new Vector3(0,0,-11)),transform.lossyScale.y*1.6f,dt)){Current=Phase.ShowNeed;clock=0;social.Memory.gatheringSite=SiteSlot(site);social.Memory.buildRequests=System.Math.Min(1000000,social.Memory.buildRequests+1);social.Memory.nextBuildingRequest=god.State.time+100;god.Journal.Add(god.State.time,"building need",CreatureAction.RespondToGuidance,GetComponent<HybridTarget>().id,"A place to rest/gather");}}
  else if(Current==Phase.ShowNeed){if(site.RecipeComplete){ResetTask();TryStructure(site);return Active;}var example=god.Targets.FirstOrDefault(t=>t.GetComponent<ConstructionInspiration>()?.recipe==BuildRecipe.Bench);motion?.LookAt(god.transform);motion?.Signal(clock%6>=3,true,clock%6<3&&example!=null?example.transform.position:site.transform.position);if(clock>20){ResetTask();TryVillageBuild(site);}}
  else {if(!site.RecipeComplete){social.Memory.buildDisappointments=System.Math.Min(1000000,social.Memory.buildDisappointments+1);ResetTask();Current=Phase.Celebrate;motion?.Signal(false,true,site.transform.position);return true;}
   if(Current==Phase.ApproachStructure){if(nav.MoveTo(structureGoal,transform.lossyScale.y*1.6f,dt)){Current=Phase.UseStructure;clock=0;motion?.Activity(0);InviteGathering();if(site.Recipe==BuildRecipe.Arch){structureGoal=site.World(new Vector3(0,0,4));nav.ResetRoute();}}}
   else if(Current==Phase.UseStructure){if(site.Recipe==BuildRecipe.Arch&&!entered)entered=nav.MoveTo(structureGoal,transform.lossyScale.y*1.6f,dt);else entered=true;var at=site.Local(transform.position);if(site.Contains(at)){var feet=transform.position;feet.y=Mathf.Max(feet.y,site.transform.position.y);transform.position=feet;}motion?.LookAt(gatheringGuest!=null?gatheringGuest.transform:site.blocks.OrderByDescending(b=>b.Body.position.y).First().transform);if(entered&&clock>(gatheringGuest!=null?24:6)){var m=social.Memory;int mask=1<<(int)site.Recipe;bool first=(m.usedForms&mask)==0;m.usedForms|=mask;RememberStructure(site);m.constructionUses=System.Math.Min(1000000,m.constructionUses+1);m.restNeed=Mathf.Max(0,m.restNeed-.45f);if(site.Recipe==BuildRecipe.Bench&&m.gatheringSite==SiteSlot(site))m.gatheringSite=-1;if(first&&site.blocks.Where(b=>b.Attached).All(b=>b.creatureBuilt)){m.trust=Mathf.Clamp01(m.trust+.06f);m.affinity=Mathf.Clamp01(m.affinity+.03f);construction.Reinforce(site.Recipe,true);god.GetComponent<CreatureCuriosity>().NoticeGreeting(transform);}god.Journal.Add(god.State.time,"structure used",CreatureAction.ConstructionPlay,GetComponent<HybridTarget>().id,site.Recipe.ToString());ResetTask();Current=Phase.Celebrate;motion?.React();}}
  }if(nav.Blocked&&elapsed>5)ResetTask();return Active;
 }
 void ReleaseStructure(){if(structure!=null){if(structure.Visitor==this)structure.Visitor=null;if(structure.Requester==this)structure.Requester=null;}structure=null;shelterVisit=false;shelterAtEntrance=false;shelteredClock=0;}
}
}
